  `threads` int(11) NOT NULL,
  `posts` int(11) NOT NULL,
  `lastPostTime` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `lastPoster` text NOT NULL,
  `lastPostId` int(11) NOT NULL,
