INSERT INTO `items` VALUES (1,'game',NULL,NULL,3,'marsoc','Sword Fights on the Heights IV',NULL,'previously:\r\nsfoth iv 11/26/25-\r\nrotris 7/31/25-11/26/25\r\nbridge wars 05/17/25-07/30/25\r\nsdc 04/20/25-05/17/25\r\nsfoth iv 02/18/25-4/20/25\r\nstress test for 02/16/25\r\nsfoth iv 12/31/24-02/15/25\r\nmarsoc\'s wwc 12/01/24-12/31/24\r\nsfoth iv 10/27/24-12/01/24\r\npirate ship 07/18/24-10/27/24',2,0,0,0,15,2976,'accepted','2025-12-14 02:30:12','2024-07-18 00:00:00',25565,NULL,'running',NULL,30,1,0,11),(2,'catalog','Hat',NULL,1,'Boomblox','Boomblox Visor','visor','Keep cool under this Boomblox visor.',1,0,8,0,8,81,'accepted','2024-07-23 00:00:00','2024-07-23 00:00:00',NULL,NULL,'stopped',NULL,0,1,0,1),(3,'catalog','Hat',NULL,1,'Boomblox','Lightbulb','Lightbulb','A lamp, in technical usage, is a replaceable component such as an incandescent light bulb, which is designed to produce light from electricity.',0,1,0,0,1,9,'accepted','2024-08-02 00:00:00','2024-08-02 14:28:00',NULL,NULL,'stopped',NULL,0,1,0,1),(4,'catalog','Hat',NULL,1,'Boomblox','Pirate Captains Hat','PirateHat','Arrr, har is a great hat. Gar. Tis fine enough for the scurviest gentleman o\\\' fortune who evar sailed the seven seas! Aye! Buy it now or walk de plank!',1,1,0,2000,5,5,'accepted','2024-08-02 00:00:00','2024-08-02 18:45:35',NULL,NULL,'stopped',NULL,0,1,0,1),(5,'catalog','Hat',NULL,1,'Boomblox','Viking Helm','VikingHelm','A sturdy Nordic helm fit for Erik the Red! Your enemies will admire your helmet\\\'s fine gold trim and ivory horns whilst you pillage their villages and set fire to all that you see!',1,1,0,125,2,13,'accepted','2024-08-02 00:00:00','2024-08-02 19:15:12',NULL,NULL,'stopped',NULL,0,1,0,1),(6,'catalog','Hat',NULL,1,'Boomblox','Red Stetson','StetsonRed',' This wide brim stetson hat is ideal for outdoor adventure. Dyed a flamboyant red, this hat is suitable for mounties and British pop stars.',1,1,0,115,4,14,'accepted','2024-08-02 00:00:00','2024-08-02 21:17:31',NULL,NULL,'stoppe