--
-- Table structure for table `messages`
--

DROP TABLE IF EXISTS `messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `messages` (
  `messageId` int(11) NOT NULL AUTO_INCREMENT,
  `senderId` int(11) DEFAULT NULL,
  `senderUn` text DEFAULT NULL,
  `recipientId` int(11) DEFAULT NULL,
  `subject` text DEFAULT NULL,
  `content` text DEFAULT NULL,
  `date` datetime NOT NULL DEFAULT current_timestamp(),
  `unread` int(11) NOT NULL DEFAULT 1,
  `archived` int(11) NOT NULL DEFAULT 0,
  `friendInvite` int(11) NOT NULL DEFAULT 0,
  `inviteActive` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`messageId`)
) ENGINE=InnoDB AUTO_INCREMENT=3471 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

