DROP TABLE IF EXISTS `threads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `threads` (
  `postId` int(11) NOT NULL AUTO_INCREMENT,
  `parentPost` int(11) DEFAULT NULL,
  `isReply` int(11) NOT NULL DEFAULT 0,
  `author` int(11) NOT NULL,
  `threadTitle` text NOT NULL,
  `threadContent` text NOT NULL,
  `postDate` datetime NOT NULL DEFAULT current_timestamp(),
  `lastActivity` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `forumId` int(11) NOT NULL,
  `pinned` int(11) NOT NULL DEFAULT 0,
  `views` text NOT NULL DEFAULT 'a:0:{}',
  PRIMARY KEY (`postId`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
