CREATE TABLE `trades` (
  `postId` int(11) NOT NULL AUTO_INCREMENT,
  `traderId` int(11) NOT NULL,
  `orderType` text NOT NULL DEFAULT 'market',
  `currency` text NOT NULL,
  `amountGiven` int(11) NOT NULL,
  `amountAsked` int(11) NOT NULL,
  `status` text NOT NULL DEFAULT 'outgoing',
  `occured` datetime NOT NULL DEFAULT current_timestamp(),
  `isSplit` int(11) NOT NULL DEFAULT 0,
  `rate` float NOT NULL,
  `remainder` int(11) NOT NULL,
  PRIMARY KEY (`postId`)
) ENGINE=InnoDB AUTO_INCREMENT=1433 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
