DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(6) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(20) NOT NULL,
  `password` varchar(255) NOT NULL,
  `email` varchar(345) DEFAULT NULL,
  `boombux` int(14) NOT NULL DEFAULT 0,
  `tix` int(14) NOT NULL DEFAULT 10,
  `blurb` varchar(416) DEFAULT NULL,
  `theme` int(11) NOT NULL DEFAULT 1,
  `characterImage` varchar(100) NOT NULL DEFAULT '09ca0e02187844ce70c2c4e5e83df3dc',
  `level` int(1) NOT NULL DEFAULT 1,
  `friends` longtext NOT NULL DEFAULT '0',
  `favorites` text DEFAULT '0',
  `items` text DEFAULT 'a:0:{}',
  `forumPosts` int(9) NOT NULL DEFAULT 0,
  `messagesIn` text DEFAULT NULL,
  `messagesOut` text DEFAULT NULL,
  `pviews` text NOT NULL DEFAULT '0',
  `kos` int(11) NOT NULL DEFAULT 0,
  `wos` int(11) NOT NULL DEFAULT 0,
  `reg_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `lastOnline` timestamp NULL DEFAULT current_timestamp(),
  `terminal` int(11) NOT NULL DEFAULT 0,
  `headColor` varchar(3) NOT NULL DEFAULT '3',
  `laColor` varchar(3) NOT NULL DEFAULT '3',
  `torsoColor` varchar(3) NOT NULL DEFAULT '2',
  `raColor` varchar(3) NOT NULL DEFAULT '3',
  `llColor` varchar(3) NOT NULL DEFAULT '11',
  `rlColor` varchar(3) NOT NULL DEFAULT '11',
  `hat` varchar(255) DEFAULT NULL,
  `head` int(11) NOT NULL DEFAULT 0,
  `shirt` varchar(255) DEFAULT NULL,
  `pants` varchar(255) DEFAULT NULL,
  `bc` int(11) NOT NULL DEFAULT 0,
  `bcExpires` timestamp NOT NULL DEFAULT current_timestamp(),
  `jointoken` varchar(255) DEFAULT NULL,
  `t-shirt` varchar(255) DEFAULT NULL,
  `event` int(11) NOT NULL DEFAULT 0,
  `joincode` varchar(255) DEFAULT NULL,
  `verified` int(14) DEFAULT NULL,
  `dynamicIp` int(14) DEFAULT 0,
  `firstIp` varchar(255) DEFAULT NULL,
  `lastIp` varchar(255) DEFAULT NULL,
  `roblosecurity` varchar(255) DEFAULT NULL,
  `clientjoin` int(11) NOT NULL DEFAULT 0,
  `clienttype` int(11) NOT NULL DEFAULT 0,
  `serverjoin` int(11) NOT NULL DEFAULT 0,
  `disease` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=133 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
